insert into public.folha_depara
  (codigo_rh, nome, departamento, categoria_descricao, origem,
   valor_referencia, valor_referencia_competencia)
select c.codigo, trim(rh.nome), c.departamento, c.categoria, c.origem,
       c.referencia, case when c.referencia is null then null else date '2026-07-01' end
from carga c
join public.rh_colaboradores rh on rh.codigo = c.codigo
on conflict (codigo_rh) do update set
  departamento                 = excluded.departamento,
  categoria_descricao          = excluded.categoria_descricao,
  origem                       = excluded.origem,
  valor_referencia             = excluded.valor_referencia,
  valor_referencia_competencia = excluded.valor_referencia_competencia;
